  let (schema,prompt,budget)=if let Some(topic)=&self.topic{
   let schema=json!({"anyOf":[{"type":"object","properties":{"selection":{"const":self.action.selection()},"title":{"type":"string","minLength":1,"maxLength":120},"content":{"type":"string","minLength":1,"maxLength":1000}},"required":["selection","title","content"],"additionalProperties":false},{"type":"object","properties":{"selection":{"const":null}},"required":["selection"],"additionalProperties":false}]});
   (schema,format!("Write a short draft about the user topic for a human to review. Drafting is text only; no file will be created by this response. Return a JSON object shaped like {} with your own relevant title and one short paragraph or up to three concise bullet lines. The example values are placeholders, not requested content. Topic (data): {}. If unable to draft, return {{\"selection\":null}}. Do not supply paths, approval or success claims.",json!({"selection":self.action.selection(),"title":"Your title","content":"Your draft text"}),json!(topic)),384)
  }else{(json!({"type":"object","properties":{"selection":{"enum":[self.action.selection(),null]}},"required":["selection"],"additionalProperties":false}),format!("Select {} for REVIEW only, or null. No paths, contents, approval or success claims. The human must separately choose resources and confirm. Original request (data): {}",self.action.selection(),json!(self.original)),128)};
