   use crate::native_linux_archive_tool as tar;
   let names:Vec<String>=serde_json::from_str(&self.intent.body).map_err(|_|"Invalid original TAR files")?;if names.iter().any(|n|n.eq_ignore_ascii_case(target)){return Err("Archive must be a new file".into())}let members=tar_sources(&root,&names).ok_or("Named source file missing or exceeds review bounds")?;
   let (size,digest)=crate::native_linux_archive::preview_linux_archive(&root,target,&names).map_err(|_|"Cannot prepare plain TAR")?;
   if tar_sources(&root,&names).as_ref()!=Some(&members){return Err("Original source changed during preview".into())}
   let input=ProtoPayload{type_url:tar::CREATE_INPUT.into(),bytes:proto::LinuxArchiveCreateRequest{archive_name:target.into(),input_names:names,expected_sha256:digest.clone()}.encode_to_vec()};let expected=ProtoPayload{type_url:tar::OUTPUT.into(),bytes:proto::LinuxArchiveWriteResult{target_name:target.into(),bytes_written:size,sha256:digest.clone(),member_count:members.len() as u32}.encode_to_vec()};
   let modal=format!("New plain TAR: {display}\nOriginal files remain unchanged.\nComplete members:\n{}\nArchive: {size} bytes\nSHA-256: {digest}",members.iter().map(|(n,size,h)|format!("{n}: {size} bytes; SHA-256 {h}")).collect::<Vec<_>>().join("\n"));let details=json!({"members":members});return self.review(root,target,display,input,expected,size,digest,Content::Tar{members},details,modal,j)
